axes[0, 1].bar(cat.index, cat.values, color=["#FF6B6B", "#4ECDC4", "#45B7D1", "#F7B731"])
axes[0, 1].set_title("Sales by category")
axes[1, 0].hist(sales["Customer_Age"], bins=15, color="purple", alpha=0.7)
axes[1, 0].set_title("Customer age")
axes[1, 1].scatter(sales["Sales"], sales["Profit"], s=10, alpha=0.5)
axes[1, 1].set_title("Sales vs profit")
fig.suptitle("Sales dashboard 2024", fontsize=16, fontweight="bold")
plt.tight_layout()
plt.show()`, o: "", img: ["img/c28-09.webp"], sum: R`
